<script lang="ts">
 import { onMount } from 'svelte';
 import { uiLanguage, setUiLanguage } from './lib/i18n-core';
 import { getLiveStatusLabel } from './lib/session-labels';
 import { formatMinutes, scoreBand } from './lib/formatting';
 type Row=Record<string,any>; type Meeting=Record<string,any>;
 let page='live', connected=false, meeting:Meeting|null=null, record:any={rows:[],summary:{}}, meetings:Meeting[]=[], configs:any={}, filter='', mode='generic', stateRevision=0, stateValue:any={mode:'generic'}, configRevision:any={}, language='en';
 let activeFilter=''; let fileInput:HTMLInputElement;
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 async function get(path:string){const r=await fetch(path);if(!r.ok)throw Error(`${r.status}`);return r.json()}
 async function refresh(){try{const s=await get('/api/meetings');meetings=s; if(meeting?.instanceId){record=await get(`/api/meetings/${meeting.instanceId}/record`)} else {meeting=meetings.find((m)=>!m.endedAt)||null;if(meeting)record=await get(`/api/meetings/${meeting.instanceId}/record`)}}catch{}}
 async function loadConfig(){for(const key of ['roster','aliases','profiles','settings']){try{const d=await get(`/api/config/${key}`);configs[key]=d.value;configRevision[key]=d.revision}catch{configs[key]=[]}}}
 async function loadState(){if(!meeting)return;try{const d=await get(`/api/meetings/${meeting.instanceId}/state`);stateRevision=d.revision;stateValue=d.value;mode=d.value.mode||'generic'}catch{}}
 async function switchMode(next:string){if(!meeting)return;mode=next;stateValue={...stateValue,mode};try{const r=await fetch(`/api/meetings/${meeting.instanceId}/state`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:stateRevision,value:stateValue})});if(r.status===409){await loadState();return}const d=await r.json();stateRevision=d.revision}catch{}}
 function summaryRows(key:string){activeFilter=key==='total'||activeFilter===key?'':key}
 $: rows=(record.rows||[]).filter((r:Row)=>{if(filter&&!`${r.canonicalName||''} ${r.zoomName||''}`.toLowerCase().includes(filter.toLowerCase()))return false;if(!activeFilter)return true;const tags=r.tags||[];return tags.includes(activeFilter)||({seen:r.hasBeenSeen,full_present:r.isCurrentlyPresent&&!r.wasLate,late:r.wasLate,returned:r.currentStatus==='returnedAfterLongAbsence',left_early:r.currentStatus==='leftEarly',missing:r.currentStatus==='missing',ignored:r.matchStatus==='guest'||r.matchStatus==='unmatched'} as any)[activeFilter]});
 onMount(()=>{language=localStorage.getItem('ui-language')||'en';const ws=new WebSocket(`ws://${location.host}/bridge`);ws.onopen=()=>{connected=true;ws.send(JSON.stringify({type:'subscribe'}))};ws.onclose=()=>connected=false;ws.onerror=()=>connected=false;ws.onmessage=(ev)=>{const m=JSON.parse(ev.data);if(m.type==='state'){meeting=m.meeting;refresh();loadState()}if(m.type==='record_updated'&&(!meeting||m.instanceId===meeting.instanceId)){refresh()}};refresh();loadConfig();return()=>ws.close()});
 async function importBackup(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const data=JSON.parse(await f.text());const r=await fetch('/api/import/attendflow-backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(r.ok){await loadConfig();alert(t('备份配置已导入','Backup configuration imported'))}else alert(t('导入失败','Import failed'))}
 function chooseLanguage(v:string){language=v;localStorage.setItem('ui-language',v);setUiLanguage(v as any)}
 const nav=[['live','◉','Live','实时'],['records','▤','Records','记录'],['configuration','⌘','Configuration','配置'],['settings','⚙','Settings','设置']];
 const stats=[['seen','Seen','到过'],['full_present','Full Present','全程到场'],['late','Late','迟到'],['returned','Returned','返回'],['left_early','Left Early','早退'],['missing','Absent','缺席'],['ignored','Ignored','不计入'],['total','Total','总计']];
</script>
<svelte:head><title>AttendFlow Desktop</title></svelte:head>
<div class="shell"><aside><div class="brand"><span class="mark">A</span><div><b>AttendFlow</b><small>DESKTOP</small></div></div><nav>{#each nav as [key,icon,en,zh]}<button class:active={page===key} onclick={()=>page=key}><span>{icon}</span>{t(zh,en)}</button>{/each}</nav><div class="connection"><i class:up={connected}></i>{connected?t('已连接','Connected'):t('正在连接','Connecting')}</div></aside><main><header><div><div class="eyebrow">{t('会议考勤','MEETING ATTENDANCE')}</div><h1>{page==='live'?t('实时会议','Live Meeting'):page==='records'?t('会议记录','Records'):page==='configuration'?t('配置','Configuration'):t('设置','Settings')}</h1></div><div class="header-actions">{#if meeting}<span class="live-pill"><i></i>{meeting.topic||meeting.meetingNumber||'Live meeting'}</span>{/if}<select value={language} onchange={(e)=>chooseLanguage(e.currentTarget.value)}><option value="en">English</option><option value="zh-CN">简体中文</option></select></div></header>
{#if page==='live'}
{#if meeting}<section class="meet-head"><div><b>{meeting.topic||t('未命名会议','Untitled meeting')}</b><small>{meeting.meetingNumber} · {new Date(meeting.startedAt).toLocaleString()}</small></div><div class="switch"><button class:chosen={mode==='generic'} onclick={()=>switchMode('generic')}>{t('通用','Generic')}</button><button class:chosen={mode==='roster'} onclick={()=>switchMode('roster')}>{t('花名册','Roster')}</button></div></section><section class="stats">{#each stats as [key,en,zh]}<button class:chosen={activeFilter===key} onclick={()=>summaryRows(key)}><small>{t(zh,en)}</small><strong>{key==='total'?record.summary?.total??0:record.summary?.[key==='full_present'?'fullPresent':key==='left_early'?'leftEarly':key]??0}</strong></button>{/each}</section><section class="toolbar"><input placeholder={t('搜索姓名…','Search names…')} bind:value={filter}/><span>{rows.length} {t('位参与者','participants')}</span></section><div class="table-wrap"><table><thead><tr><th>{t('姓名','Name')}</th><th>{t('Zoom 名称','Zoom name')}</th><th>{t('状态','Status')}</th><th>{t('位置','Location')}</th><th>{t('小组','Group')}</th><th>{t('首次加入','First join')}</th><th>{t('最近进出','Last seen')}</th><th>{t('分钟','Minutes')}</th>{#if meeting.isHost}<th>{t('等候室分钟','Waiting')}</th>{/if}</tr></thead><tbody>{#each rows as r}<tr><td><b>{r.canonicalName||r.zoomName}</b></td><td>{r.zoomName}</td><td><span class="chip">{getLiveStatusLabel(r.currentStatus,language as any)}</span></td><td>{r.currentLocation||'—'}</td><td>{r.group||'—'}</td><td>{r.firstJoinAt?new Date(r.firstJoinAt).toLocaleTimeString():'—'}</td><td>{r.lastSeenAt?new Date(r.lastSeenAt).toLocaleTimeString():'—'}</td><td>{formatMinutes(r.totalPresenceMinutes)}</td>{#if meeting.isHost}<td>{Math.round(r.waitingRoomMinutes||0)}</td>{/if}</tr>{:else}<tr><td colspan="9" class="empty">{t('等待参与者事件…','Waiting for participant events…')}</td></tr>{/each}</tbody></table></div>{:else}<section class="empty-card"><span>◉</span><h2>{t('尚未加入会议','No active meeting')}</h2><p>{t('连接后，会议记录会自动显示在这里。','When you join a meeting, its attendance record will appear here.')}</p></section>{/if}
{:else if page==='records'}<div class="records-grid"><section class="panel"><h2>{t('所有会议','All meetings')} <small>{meetings.length}</small></h2>{#each meetings as m}<button class="meeting-row" onclick={async()=>{meeting=m;record=await get(`/api/meetings/${m.instanceId}/record`);mode=record.mode||'generic';page='records'}}><span class="avatar">◷</span><span class="meeting-label"><b>{m.topic||m.meetingNumber}</b><small>{new Date(m.startedAt).toLocaleString()} · {m.isHost?t('主持人','Host'):t('参与者','Attendee')}</small></span><span class="score">{m.endedAt?t('已结束','Ended'):t('进行中','Live')}</span></button>{/each}</section>{#if meeting}<section class="panel"><h2>{meeting.topic||meeting.meetingNumber}</h2><div class="switch"><button class:chosen={mode==='generic'} onclick={()=>switchMode('generic')}>{t('通用','Generic')}</button><button class:chosen={mode==='roster'} onclick={()=>switchMode('roster')}>{t('花名册','Roster')}</button></div><p class="muted">{record.summary?.total??0} {t('位参与者','participants')}</p><div class="table-wrap"><table><thead><tr>{#if mode==='roster'}<th>{t('花名册姓名','Roster name')}</th><th>{t('Zoom 名称','Zoom name')}</th><th>{t('小组','Group')}</th>{:else}<th>{t('姓名','Name')}</th>{/if}<th>{t('状态','Status')}</th><th>{t('分数','Score')}</th><th>{t('出席分钟','Minutes')}</th></tr></thead><tbody>{#each record.rows||[] as r}<tr>{#if mode==='roster'}<td>{r.canonicalName||'—'}</td><td>{r.zoomName}</td><td>{r.group||'—'}</td>{:else}<td>{r.zoomName}</td>{/if}<td><span class="chip">{getLiveStatusLabel(r.currentStatus,language as any)}</span></td><td><span class="score" class:excellent={scoreBand(r.score)==='excellent'} class:good={scoreBand(r.score)==='good'} class:fair={scoreBand(r.score)==='fair'} class:low={scoreBand(r.score)==='low'} class:zero={scoreBand(r.score)==='zero'}>{Math.round(r.score||0)}%</span></td><td>{formatMinutes(r.totalPresenceMinutes)}</td></tr>{/each}</tbody></table></div></section>{/if}</div>
{:else if page==='configuration'}<section class="panel"><div class="panel-title"><div><h2>{t('AttendFlow 配置','AttendFlow configuration')}</h2><p>{t('查看已导入的花名册、别名和考勤配置。','Review imported roster, aliases, and attendance profiles.')}</p></div><button class="primary" onclick={()=>fileInput.click()}>＋ {t('导入备份','Import backup')}</button><input bind:this={fileInput} type="file" accept="application/json,.json" hidden onchange={importBackup}/></div><div class="config-grid">{#each [['roster','Roster','花名册'],['aliases','Aliases','别名'],['profiles','Profiles','考勤配置']] as [key,en,zh]}<section class="config-card"><div class="config-header"><h3>{t(zh,en)}</h3><span>{Array.isArray(configs[key])?configs[key].length:0}</span></div>{#each (Array.isArray(configs[key])?configs[key]:[]) as item}<div class="config-item"><b>{item.canonicalName||item.name||item.zoomName||item.id||'—'}</b><small>{item.group||item.alias||item.description||''}</small></div>{:else}<p class="muted">{t('尚无数据','No imported data')}</p>{/each}</section>{/each}</div></section>
{:else}<section class="panel settings"><h2>{t('语言','Language')}</h2><p>{t('选择界面语言。','Choose the interface language.')}</p><div class="language-options"><button class:chosen={language==='zh-CN'} onclick={()=>chooseLanguage('zh-CN')}>简体中文</button><button class:chosen={language==='en'} onclick={()=>chooseLanguage('en')}>English</button></div><div class="about"><span class="mark">A</span><div><b>AttendFlow Desktop</b><small>Zoom Companion · Local-only attendance records</small></div></div></section>{/if}</main></div>






